import{_ as a,o as t,c as r,a5 as o}from"./chunks/framework.QWVCgkrI.js";const s="/study/images/game/asset-pack-files.svg",p=JSON.parse('{"title":"ゲームのアセットをパックファイルにまとめる","description":"","frontmatter":{"title":"ゲームのアセットをパックファイルにまとめる","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"ヘッダー、目次、データ本体でアセットの範囲を特定する。配置と読み取りの単位、チャンク圧縮、ファイルを開いたときの検査を扱う。","aliases":["パックファイル","アセットパック","archive","目次","TOC","asset ID","offset","payload","チャンク圧縮","パディング"],"verification":"MicrosoftのDirectStorageとファイルバッファリングの資料、UnityのAssetBundle資料に照合（2026-11-06）"}},"headers":[],"relativePath":"game/asset-pack-files.md","filePath":"game/asset-pack-files.md"}'),i={name:"game/asset-pack-files.md"};function d(n,e,c,l,h,f){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="ゲームのアセットをパックファイルにまとめる" tabindex="-1">ゲームのアセットをパックファイルにまとめる <a class="header-anchor" href="#ゲームのアセットをパックファイルにまとめる" aria-label="Permalink to &quot;ゲームのアセットをパックファイルにまとめる&quot;">​</a></h1><p>レベルのメッシュ、テクスチャ、衝突データを一つのファイルにまとめると、ローダーはファイルを開き、その中から必要な範囲を読み取れます。例えばテクスチャが必要になったら、<strong>目次</strong>（TOC、Table of Contents）でアセットIDを引き、ファイル先頭からの位置（オフセット）とバイト数を得ます。書き出す側と読み取る側で、この位置の基準やデータの並べ方を決めておきます。<a href="/study/game/asset-loading.html">実行時のアセットロード設計</a></p><figure class="study-figure"><img src="'+s+'" alt="パックファイルはヘッダー、目次、データ本体の順に並ぶ。テクスチャのIDを目次から引き、ファイル先頭を基準とするオフセットと長さを得て、テクスチャの範囲を読み取る。" width="760" height="438" loading="lazy"><figcaption>目次を先頭近くに置いた構成例です。ヘッダーと目次から各範囲を特定し、使うデータを読み取ります。<a href="/study/images/game/asset-pack-files.svg" target="_blank" rel="noopener noreferrer">パックの構成図を拡大</a></figcaption></figure><h2 id="ヘッダー、目次、データ本体" tabindex="-1">ヘッダー、目次、データ本体 <a class="header-anchor" href="#ヘッダー、目次、データ本体" aria-label="Permalink to &quot;ヘッダー、目次、データ本体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>部分</th><th>主に入れる情報</th></tr></thead><tbody><tr><td>ヘッダー</td><td>形式を識別するマジック、版、目次の位置や項目数。読み取り側が後続のバイト列を解釈する入口。</td></tr><tr><td>目次</td><td>アセット名やIDと、データのオフセット・格納サイズとの対応。圧縮する場合は展開方式や展開後サイズも持てる。</td></tr><tr><td>データ本体</td><td>配布用に変換したアセットのバイト列。必要な場合はアラインメントをそろえるための詰め物（パディング）も入る。</td></tr></tbody></table><p>IDは、ゲームが「どのアセットか」を指すための値です。ファイル内の位置は作り直すたびに変わり得るので、ゲーム側は目次を通して位置を得ます。名前をそのまま格納する方式なら名前の長さや文字の規則を決め、名前からハッシュ値を作る方式なら衝突を検出・解決する方法を決めます。</p><p>例えば実践で使う <code>SPAK</code> では、先頭の4バイトがマジック、続く2個の32ビット符号なし整数が版と項目数です。目次は1件24バイトで、16バイトの名前欄と、各4バイトのオフセット・格納サイズを並べます。名前はASCIIの英小文字・数字・<code>_</code>・<code>-</code>で1〜15文字とし、余ったバイトをゼロで埋めます。数値はリトルエンディアンです。こうして各フィールドのバイト数と順番を明示すると、読み取り側は同じ規則でバイト列を解析でき、C++の構造体のパディングや、実行環境のバイト順から独立した形式になります。<a href="/study/data/integer-bits-and-bytes.html">整数とエンディアン</a> · <a href="/study/practice/io/asset-pack-observation.html">C++のアセットパック実践</a></p><h2 id="使うまとまりと読み取るまとまり" tabindex="-1">使うまとまりと読み取るまとまり <a class="header-anchor" href="#使うまとまりと読み取るまとまり" aria-label="Permalink to &quot;使うまとまりと読み取るまとまり&quot;">​</a></h2><p>ビルド時に、起動時に揃えるデータ、同じステージで使うデータ、複数のステージから参照する共有データを見分けます。同時に必要な小さなアセットを近くへ配置しておくと、一続きの範囲としてまとめて読めます。一方、先に必要なHUDの小さな画像と、後で使う大きな地形データを常に一緒に読むと、HUDを準備するまでの待ち時間や受け取りバッファが増えます。起動、ステージ遷移、移動中の先読みなど、実際にロードする順番から配置と優先度を決めます。<a href="/study/os/windows-file-cache.html">Windowsのファイルキャッシュと先読み</a></p><p>一つの要求にまとめると呼び出しや完了処理の回数を減らせます。間にある不要なデータまで読む場合は、読み取る総バイト数が増えます。離れたアセットを別の要求に分ける場合は、同時発行数とバッファの合計に上限を置きます。変更前後で、要求数・読み取り量・必要なアセットが揃うまでの時間を比べます。<a href="/study/tools/windows/file-io-tracing.html">WindowsのファイルI/O計測</a></p><p>パディングを入れるなら、理由と境界を形式に定めます。例えばWindowsの <code>FILE_FLAG_NO_BUFFERING</code> を使う経路では、ファイルのオフセットと要求サイズにセクター単位の制約があり、受け取りバッファにもアラインメントを考慮します。パックの配置をそろえても、メモリ上のバッファの条件は別に確認します。パディングが増えると配布サイズや読み取り量が増えるので、利用するAPIの条件に合わせます。<a href="https://learn.microsoft.com/en-us/windows/win32/fileio/file-buffering#alignment-and-file-access-requirements" target="_blank" rel="noreferrer">Microsoftのファイルバッファリング仕様</a></p><h2 id="圧縮する場合は、どこから展開できるかを決める" tabindex="-1">圧縮する場合は、どこから展開できるかを決める <a class="header-anchor" href="#圧縮する場合は、どこから展開できるかを決める" aria-label="Permalink to &quot;圧縮する場合は、どこから展開できるかを決める&quot;">​</a></h2><p>全体を一つの圧縮ストリームにすると、途中のアセットにオフセットを付けるだけでは、そこから直ちに展開できるとは限りません。個別に読みたい範囲は<strong>独立に展開できるチャンク</strong>に分け、その格納オフセット、圧縮後のサイズ、展開後のサイズ、方式を目次から引けるようにします。例えば地形の区画を別々のチャンクにすると、現在地の近くにある区画の圧縮データだけを読み取れます。小さいチャンクを増やすと細かく読める一方で、目次や各チャンクの管理が増え、圧縮率にも影響します。<a href="https://docs.unity3d.com/ja/6000.0/ScriptReference/CompressionType.html" target="_blank" rel="noreferrer">Unity 6のAssetBundle圧縮方式</a></p><p>DirectStorageで圧縮データを読む場合も、各要求に渡すデータをその範囲だけで展開できる必要があります。Microsoftの <code>BulkLoadDemo</code> では、モデルとテクスチャをパックにまとめるツールが、ステージングバッファに収まるよう要求を分割します。データを読み取ったあと、必要に応じて展開し、GPUやエンジン側の準備を終えてからアセットを利用します。<a href="https://github.com/microsoft/DirectStorage/blob/main/Docs/DeveloperGuidance.md#compressed-assets" target="_blank" rel="noreferrer">MicrosoftのDirectStorage開発ガイド</a> · <a href="https://github.com/microsoft/DirectStorage/blob/main/Samples/BulkLoadDemo/README.md#building-marc-files" target="_blank" rel="noreferrer">公式BulkLoadDemo</a> · <a href="/study/game/directstorage.html">DirectStorageの仕組み</a></p><h2 id="目次を検査してから読み取る" tabindex="-1">目次を検査してから読み取る <a class="header-anchor" href="#目次を検査してから読み取る" aria-label="Permalink to &quot;目次を検査してから読み取る&quot;">​</a></h2><p>最初にマジックと版を確認し、項目数から求めた目次のサイズがファイルに収まるかを確かめます。各データは目次より後ろにあり、宣言された範囲がファイル内に収まる必要があります。サイズ検査では、オフセットがファイル長以内かを先に確かめ、残りの <code>ファイル長 - オフセット</code> と格納サイズを比較すると、加算の桁あふれを避けられます。IDの重複、同じ領域の共有を許すかどうか、圧縮後と展開後のサイズ上限も形式の規則に含めます。<a href="/study/data/binary-file-validation.html">バイナリファイルの検査</a></p><p>形式にチェックサムを持たせる場合は、どの範囲のどの状態を検査するかを決めます。例えば格納したバイトのチェックサムを展開前に照合すると、読み取った圧縮データの破損を検出できます。目次のサイズやデータ範囲は先に検査し、読み取れる範囲を確定します。配布元の真正性も必要な場合は、署名の検証などを別に設計します。実践では小さなパックを作り、目次から指定されたアセットを読み取り、壊れたパックが拒否されることを確認できます。<a href="/study/practice/io/asset-pack-observation.html">C++でパックを作って読む</a></p>',17)])])}const u=a(i,[["render",d]]);export{p as __pageData,u as default};
